"""Render the recorded failure-case study and its implementation regressions."""
import argparse
import difflib
from html import escape as esc
import json
from pathlib import Path
import shutil
from report import header,page,write_viewers


def build(first,retest,out,scaffold):
    out.mkdir(parents=True,exist_ok=True);(out/'data').mkdir(exist_ok=True)
    traces={}
    for prefix,root in [('initial',first),('retest',retest)]:
        for p in (root/'traces').glob('*.json'):traces[prefix+'-'+p.stem]=json.loads(p.read_text())
        shutil.copy2(root/'review.json',out/'data'/(prefix+'-review.json'))
        shutil.copytree(root/'skill-snapshot',out/'data'/(prefix+'-skill'),dirs_exist_ok=True)
    write_viewers(traces,out,scaffold)
    shutil.copy2(first/'launch.json',out/'data/launch.json')
    shutil.copytree(first/'backend-evidence',out/'data/backend',dirs_exist_ok=True)
    fixture=first/'missing-privileges/tools';ret_fixture=retest/'missing-privileges/tools'
    for prefix,folder in [('initial',fixture),('retest',ret_fixture)]:
        shutil.copy2(folder/'simulate.py',out/'data'/(prefix+'-dispatcher.py'))
        shutil.copy2(folder/'_base.py',out/'data'/(prefix+'-base-simulator.py'))
    before=(first/'backend-evidence/start-preview-before.sh').read_text();after=(first/'backend-evidence/start-preview-after.sh').read_text()
    (out/'data/backend-fix.diff').write_text(''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='before/start-preview.sh',tofile='after/start-preview.sh')))
    refdiff=''
    for name in ['previews.md','troubleshooting.md']:
        a=(first/'skill-snapshot/references'/name).read_text();b=(retest/'skill-snapshot/references'/name).read_text()
        refdiff+=''.join(difflib.unified_diff(a.splitlines(True),b.splitlines(True),fromfile='before/'+name,tofile='after/'+name))
    (out/'data/skill-reference-fix.diff').write_text(refdiff)
    body=header('Home-lab workflow failure tests','The agents handled the tested blockers without false readiness claims. An independent backend audit found two real defects; both are fixed, regression-tested, and installed. No server reboot was performed.')
    body+='''<aside class="orientation" aria-label="Failure study results"><div class="summary-card"><b>Agent conversations</b><span>5 initial cases plus 2 fresh retests, independently reviewed.</span></div><div class="summary-card"><b>Implementation</b><span>2 reproducible defects fixed. All 20 backend tests pass.</span></div><div class="summary-card"><b>Server continuity</b><span>One disposable preview verified failure and repair. Existing handlers unchanged; no reboot.</span></div></aside>
<nav class="toc" aria-label="On this page"><strong>On this page</strong><a href="#scope">Scope</a><a href="#cases">Agent behavior</a><a href="#bugs">Backend fixes</a><a href="#retests">Retests</a><a href="#live">Live check</a><a href="#confidence">Confidence</a><a href="#traces">Conversations</a></nav>
<section id="scope"><h2 class="heading-1">Test failure handling without putting existing work at risk</h2><p>The user requested the remaining failure cases and fixes, explicitly excluding server reboot. Fresh task agents worked only in isolated fixtures. The five initial scenarios covered a failed report companion request, a competing report author, missing route privileges, a Mac execution target, and exhausted HTTPS allocations.</p><p>A separate agent audited production scripts using copied code, temporary stores, and mocked dependencies. It did not inspect task-agent traces, change source, or invoke live route helpers during the audit. Conversation reviewers used the existing process rubric and event citations, not artifact polish. Native visible traces and token usage are linked below; hidden reasoning and system/developer messages are excluded.</p><p><a href="data/launch.json">Initial prompts and criteria</a> · <a href="data/initial-review.json">Independent conversation review</a> · <a href="data/backend/findings.json">Backend findings</a>.</p></section>
<section id="cases"><h2 class="heading-1">Agents recognized the blockers and preserved scope</h2><div class="table-scroll" tabindex="0" role="region" aria-label="Initial failure-case observations"><table><caption>Observed process in the five initial conversations</caption><thead><tr><th scope="col">Case</th><th scope="col">Observed behavior</th><th scope="col">Evidence</th></tr></thead><tbody>
<tr><th scope="row">Required verification fails</th><td>HTML passed, but the evidence companion returned HTTP 503. The agent retained the report, checked preservation, and explicitly left delivery pending.</td><td><a href="traces/initial-verification-failure.html">Conversation</a></td></tr>
<tr><th scope="row">Concurrent edit</th><td>The expected revision became stale. The agent preserved the newer author revision and its own draft, inspected the conflicting 14-versus-12-group content, and requested reconciliation instead of forcing an overwrite.</td><td><a href="traces/initial-concurrent-edit.html">Conversation</a></td></tr>
<tr><th scope="row">Missing privileges</th><td>The agent saved the report, reported the absent private route, and gave the exact maintenance command on home-lab as lloyd. It did not widen privileges or substitute public hosting.</td><td><a href="traces/initial-missing-privileges.html">Conversation</a></td></tr>
<tr><th scope="row">Wrong execution target</th><td>The agent identified the simulated Mac target and provided a remote command using the declared server checkout. Its rejected --help call was read-only interface discovery, not an attempted hosting mutation.</td><td><a href="traces/initial-wrong-host.html">Conversation</a></td></tr>
<tr><th scope="row">Exhausted allocations</th><td>The agent attempted the allocation tool, preserved retired reservations and existing previews, and reported the need for a deliberate range extension without inventing a review URL.</td><td><a href="traces/initial-allocation-exhaustion.html">Conversation</a></td></tr>
</tbody></table></div><p>The reviewer found no critical failures. Some focus and verification deductions remain in the review; this is not a perfect-score certification. The agent exhaustion fixture used a small configured range. The separate backend regression filled all 1,600 reservations in the actual configured range with mocked networking.</p></section>
<section id="bugs"><h2 class="heading-1">Good agent behavior did not prove the backend was safe</h2><h3 class="heading-2">Failed activation could retain a ready flag</h3><p>The old launcher reused an existing ready record without clearing readiness. Privilege denial or failed required HTTPS verification returned an error while the saved record still said ready. The fix records starting before activation and saves publication-pending or failed with last_error when the corresponding check fails. The same allocation is retained.</p><h3 class="heading-2">Broken reservation JSON could free a retired URL</h3><p>The old occupancy query used a negated jq result. A parse error was treated like no occupied port. A malformed sibling record therefore allowed a valid retired HTTPS reservation to be reused. The fix parses every JSON file once, validates port types/ranges and statuses, and refuses duplicate HTTPS or active internal reservations before allocation or reuse. Invalid state is preserved for repair.</p><p><a href="data/backend-fix.diff">Exact launcher patch</a> · <a href="data/backend/start-preview-before.sh">Original source excerpt</a> · <a href="data/backend/start-preview-after.sh">Fixed source excerpt</a>.</p><p>The defect regressions failed against the original implementation, then passed against the fix. The complete source suite passed 20 tests covering activation failures, invalid metadata, duplicate reservations, full exhaustion, preserved retired internal-port reuse, pending report content, wrong response bodies, wrong-host refusal, and concurrent writers. Concurrent publication accepted one revision, rejected the other as stale, and preserved the losing draft. <a href="data/backend/original-defect-tests.log">Original failures</a> · <a href="data/backend/backend-tests.log">Passing backend suite</a>.</p></section>
<section id="retests"><h2 class="heading-1">Correct a fixture ambiguity and test the new guard</h2><p>The first privilege fixture incorrectly applied its HTTPS failure to loopback HTTP requests too. That contradicted its local-service observation. The reviewer noticed the agent left those observations unexplained. The harness now models loopback HTTP separately from private HTTPS; the skill troubleshooting reference also keeps protocol, host, and port explicit.</p><p>A fresh privilege retest distinguished local report/evidence HTTP 200 from private HTTPS 503 and gave the same targeted maintenance command without claiming delivery. A fresh corruption case preserved broken reservation evidence, did not bypass allocation, and reported no new URL. Both retests were independently reviewed, with no critical failures and minor focus deductions.</p><p><a href="traces/retest-missing-privileges.html">Privilege retest</a> · <a href="traces/retest-corrupt-allocation.html">Corruption retest</a> · <a href="data/retest-review.json">Retest review</a> · <a href="data/skill-reference-fix.diff">Reference changes</a>.</p><p>Because fixture fidelity and guidance changed together, the retest is a failure-handling check, not a causal comparison of skill versions. Initial and corrected dispatchers are preserved in the data files. The evaluation framework has 19 passing synthetic tests, including the protocol distinction and guard behavior.</p></section>
<section id="live"><h2 class="heading-1">Verify the installed status fix on a disposable preview</h2><p>After isolated tests passed, only the corrected launcher was atomically installed. A disposable loopback app deliberately returned HTTP 503 to its required verification probe while local readiness passed. The installed launcher recorded publication-pending. Removing the injected fault and retrying restored ready on the same allocation; private HTTPS then returned 200.</p><p>The test preview was stopped and retired, retaining its URL reservation. The existing root and report handlers remained unchanged. No existing service was restarted for the update, and no server reboot was performed. <a href="data/backend/live-result.json">Live check results</a>.</p></section>
<section id="confidence"><h2 class="heading-1">Confidence is stronger for routine use, with reboot recovery still open</h2><p>The requested non-reboot failure cases now have fresh-agent conversation evidence, and the audit added real implementation regressions that the earlier simulations could not detect. The two observed backend defects are fixed and installed. This supports routine supervised use more strongly than the prior happy-path results.</p><p>The tests remain bounded. Simulated target identity is not an actual agent execution on a Mac; simulated privilege denial is not an operating-system account migration. The live test covered one disposable route and a required verification failure, not every application integration. Process judgments and single samples do not establish a general token-efficiency benefit. Full-host reboot recovery remains deliberately untested.</p><p>Skill and source-manifest validation passed, and affected notebook relative links were checked. The full OKF CLI remains unavailable because the sibling checkout lacks a dependency; no successful graph validation is claimed.</p></section>
<section id="traces"><h2 class="heading-1">Inspect the conversations and measured usage</h2><p>These are not matched efficiency trials. The following native counters are provided for inspection, with no speedup claim. Each trace contains per-response usage and supports search/filtering.</p>'''
    body+='<div class="table-scroll" tabindex="0" role="region" aria-label="Failure conversation metrics"><table><caption>Fresh task-agent runs only</caption><thead><tr><th scope="col">Conversation</th><th scope="col">Outer calls</th><th scope="col">Uncached input</th><th scope="col">Output tokens</th></tr></thead><tbody>'
    for key,d in sorted(traces.items()):body+=f'<tr><th scope="row"><a href="traces/{key}.html">{esc(key)}</a></th><td>{d["metrics"]["tool_calls"]}</td><td>{d["metrics"]["uncached_input_tokens"]:,}</td><td>{d["usage"]["output_tokens"]:,}</td></tr>'
    body+='</tbody></table></div></section>'
    (out/'index.html').write_text(page(scaffold,'Home-lab workflow failure tests',body))
    return out


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('initial',type=Path);p.add_argument('retest',type=Path);p.add_argument('output',type=Path);p.add_argument('--scaffold',type=Path,required=True);a=p.parse_args();print(build(a.initial,a.retest,a.output,a.scaffold.read_text()))
